#!/usr/bin/env python3
"""Exercise pkg_add updates using tiny packages generated by pkg_create.

Usage: python3 test.py STAGED_PKG_ADD STAGED_PKG_DELETE RUNTIME_LIB PKG_CREATE
The test creates and deletes only temporary data.
"""
import os
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile

pkg_add, pkg_delete, runtime_lib, pkg_create = map(lambda x: Path(x).resolve(strict=True), sys.argv[1:])


def run(argv, env, cwd, success):
    p = subprocess.run([str(x) for x in argv], cwd=cwd, env=env,
                       stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
    if (p.returncode == 0) != success:
        raise AssertionError(f'{argv}: exit {p.returncode}\n{p.stdout}')
    return p


with tempfile.TemporaryDirectory(prefix='pkg-add-sibling-') as tmp:
    root = Path(tmp)
    source = root / 'source'
    source.mkdir()
    fixture_list = root / 'PLIST'
    fixture_list.write_text('@cwd ' + str(source) + '\nmessage\n')
    uname = os.uname()
    machine = {'arm64': 'aarch64', 'amd64': 'x86_64'}.get(uname.machine, uname.machine)
    info = root / 'BUILD_INFO'
    info.write_text(f'OPSYS={uname.sysname}\nOS_VERSION={uname.release}\nMACHINE_ARCH={machine}\n')
    archives = []
    for version in ('1.0', '2.0'):
        (source / 'message').write_text('version ' + version + '\n')
        archive = root / ('fixture-' + version + '.tgz')
        run([pkg_create, '-c', '-fixture', '-d', '-fixture', '-f', fixture_list,
             '-B', info, '-p', source, '-I', '/usr/pkg', archive], os.environ, root, True)
        archives.append(archive)
    old, new = archives
    tool = root / 'tool'
    (tool / 'sbin').mkdir(parents=True)
    (tool / 'lib').symlink_to(runtime_lib, target_is_directory=True)
    shutil.copy2(pkg_add, tool / 'sbin/pkg_add')
    helper = tool / 'sbin/pkg_delete'
    log = root / 'args'
    helper.write_text('#!/bin/sh\nprintf "%s\\n" "$@" > "$CAPTURE"\nexit 71\n')
    helper.chmod(0o755)
    conf = root / 'pkg_install.conf'
    conf.write_text('VERIFIED_INSTALLATION=never\nPKG_PATH=\n')
    env = dict(os.environ, CAPTURE=str(log), PATH=str(tool / 'sbin') + os.pathsep + '/usr/bin:/bin')
    link = root / 'symlinks'
    link.mkdir()
    (link / 'pkg_add').symlink_to(tool / 'sbin/pkg_add')

    for mode in ('absolute', 'relative', 'path', 'empty-path', 'symlink', 'target', 'success', 'missing', 'nonexecutable'):
        case = root / mode
        prefix = case / 'prefix'
        db = case / 'pkgdb'
        prefix.mkdir(parents=True)
        db.mkdir()
        if mode == 'target':
            dest = case / 'target-root'
            (dest / 'usr/pkg').mkdir(parents=True)
            (dest / 'var/db/pkg').mkdir(parents=True)
            db_arg, prefix_arg = '/var/db/pkg', '/usr/pkg'
            base = [tool / 'sbin/pkg_add', '-C', conf, '-P', dest, '-I', '-K', db_arg, '-p', prefix_arg]
        else:
            db_arg, prefix_arg = str(db), str(prefix)
            base = [tool / 'sbin/pkg_add', '-C', conf, '-K', db_arg, '-p', prefix_arg]
        run(base + [old], env, root, True)
        log.unlink(missing_ok=True)
        before = {str(p.relative_to(case)): p.read_bytes() for p in case.rglob('*') if p.is_file()}
        local_env = env.copy()
        cwd = root
        executable = str(tool / 'sbin/pkg_add')
        if mode == 'relative':
            executable = 'tool/sbin/pkg_add'
        elif mode == 'path':
            executable = 'pkg_add'
        elif mode == 'empty-path':
            executable = 'pkg_add'
            cwd = tool / 'sbin'
            local_env['PATH'] = ':/usr/bin:/bin'
        elif mode == 'symlink':
            executable = str(link / 'pkg_add')
        elif mode == 'success':
            helper.unlink()
            shutil.copy2(pkg_delete, helper)
        elif mode == 'missing':
            helper.unlink()
        elif mode == 'nonexecutable':
            helper.write_text('#!/bin/sh\nexit 71\n')
            helper.chmod(0o644)
        command = [executable, '-C', conf, '-v', '-U', '-K', db_arg, '-p', prefix_arg]
        if mode == 'target':
            command += ['-P', dest, '-I']
        command += [new]
        result = run(command, local_env, cwd, mode == 'success')
        if mode == 'success':
            assert (prefix / 'message').read_text() == 'version 2.0\n'
            assert (db / 'fixture-2.0').is_dir()
            assert not (db / 'fixture-1.0').exists()
            helper.unlink()
            helper.write_text('#!/bin/sh\nprintf "%s\\n" "$@" > "$CAPTURE"\nexit 71\n')
            helper.chmod(0o755)
        elif mode in ('missing', 'nonexecutable'):
            assert not log.exists(), result.stdout
            assert str(helper) in result.stdout, result.stdout
            after = {str(p.relative_to(case)): p.read_bytes() for p in case.rglob('*') if p.is_file()}
            assert before == after, 'package payload or pkgdb changed'
        else:
            assert log.exists(), result.stdout
            args = log.read_text().splitlines()
            expected = ['-K', db_arg, '-p', prefix_arg]
            if mode == 'target':
                expected = ['-D'] + expected + ['-P', str(dest)]
            assert args[:-1] == expected, args
            assert str(helper) in result.stdout, result.stdout
        print(mode, 'PASS')

print('Invocation, native and target helper flags, and fail-closed checks passed.')
